"""Microéconomie — cours rédigés pour être compris (style Écosphère), d'après l'intro,
le chapitre 1 (théorie du consommateur, 6 fichiers) et le chapitre 2 (théorie du producteur, 3 séances)."""
from lib import Cours, table, ul


def ch0():
    c = Cours()
    c.intro('De quoi parle ce cours ?',
            'La microéconomie étudie les <b>décisions individuelles</b> : comment un consommateur choisit ce qu\'il achète avec son budget, comment une entreprise choisit comment produire au moindre coût. Ton cours se concentre sur ces deux agents. Cette introduction pose le décor : les hypothèses de base et le fonctionnement d\'un marché.',
            ['Qu\'est-ce qui distingue la micro de la macro ?', 'Sur quelles hypothèses repose le raisonnement ?', 'Comment se forme un prix sur un marché ?'])

    c.sec('I. Qu\'est-ce que la microéconomie ?')
    c.idee('La micro part de l\'<b>individu</b> pour expliquer l\'économie ; la macro part des <b>grands agrégats</b> (production nationale, chômage, inflation).')
    c.df('Microéconomie', 'Analyse des choix et des comportements des agents individuels (consommateurs, producteurs) ; elle adopte la démarche de l\'individualisme méthodologique.')
    c.df('Macroéconomie', 'Analyse des agrégats économiques qui gomme la diversité des comportements en recourant à un agent représentatif.')
    c.autrement('la micro regarde les arbres un par un, la macro regarde la forêt. Mais la forêt est faite d\'arbres : la demande totale d\'un bien est la somme des demandes individuelles.')
    c.f('Demande totale = Σ demandes individuelles · Offre totale = Σ offres individuelles')
    c.h3('Deux hypothèses fondamentales')
    c.df('Principe de rationalité', 'Les agents ont des objectifs bien déterminés qu\'ils cherchent à atteindre au mieux en respectant les contraintes qui limitent leurs choix ; la micro ne s\'interroge pas sur l\'origine de ces objectifs.')
    c.autrement('on ne demande pas <i>pourquoi</i> quelqu\'un aime le chocolat ; on suppose qu\'il le sait, et on étudie comment il fait au mieux avec son budget. C\'est le problème de l\'<b>allocation de ressources rares sous contrainte</b>.')
    c.df('Échange marchand', 'Échange au prix du marché, volontaire et mutuellement avantageux.')
    c.df('Marché', 'Mécanisme qui assure la confrontation, à un moment donné, de l\'offre et de la demande d\'un bien ou d\'un service et conduit à la détermination d\'un prix.')
    c.retenir(['Micro = choix individuels (individualisme méthodologique).', 'Deux hypothèses : rationalité (maximiser sous contrainte) et échange marchand volontaire.'])
    c.transition('Pour analyser un marché de façon simple, on part d\'un cas idéal : la concurrence pure et parfaite.')

    c.sec('II. La concurrence pure et parfaite (CPP)')
    c.idee('La CPP est un <b>modèle de référence</b> : un marché idéal où personne n\'a de pouvoir sur le prix. La réalité s\'en écarte, mais c\'est la base de comparaison.')
    c.p('Cinq hypothèses : les trois premières font une concurrence <b>pure</b>, les deux dernières la rendent <b>parfaite</b>.')
    c.df('Atomicité des acteurs', 'Nombre d\'offreurs et de demandeurs très élevé : l\'offre ou la demande de chaque agent est négligeable, chacun est preneur de prix (price taker).')
    c.autrement('comme un atome dans un corps, chaque acheteur ou vendeur est trop petit pour influencer le prix : il le subit.')
    c.df('Homogénéité des produits', 'Les biens échangés sur un marché sont interchangeables : les consommateurs sont indifférents à l\'identité du vendeur ; un marché par nature de bien.')
    c.df('Libre entrée et libre sortie', 'Chaque agent peut entrer sur le marché et en sortir à tout moment sans coût : pas de barrières (brevets, investissements élevés ou spécifiques, lois, frais de résiliation).')
    c.df('Transparence de l\'information', 'L\'information nécessaire aux choix des agents est librement disponible et connue de tous.')
    c.df('Mobilité parfaite des facteurs', 'Libre circulation du capital et du travail, qui assure une allocation efficace des moyens de production.')
    c.retenir(['Pure : atomicité, homogénéité, libre entrée et sortie.', 'Parfaite : transparence, mobilité des facteurs.', 'Conséquence : chacun est preneur de prix.'])
    c.transition('Sur un tel marché, le prix résulte de la rencontre de l\'offre et de la demande.')

    c.sec('III. Offre, demande et équilibre')
    c.df('Courbe de demande', 'Quantité que les acheteurs sont disposés à acheter pour chaque niveau de prix, toutes choses égales par ailleurs ; pour la plupart des biens, la demande diminue avec le prix.')
    c.df('Courbe d\'offre', 'Quantité que les vendeurs sont disposés à vendre pour chaque niveau de prix, toutes choses égales par ailleurs ; l\'offre augmente avec le prix.')
    c.p('Deux types d\'acteurs : les <b>demandeurs</b> (ménages, entreprises) et les <b>offreurs</b> (entreprises, travailleurs).')
    c.h3('Se déplacer « le long » ou déplacer « la » courbe ?')
    c.idee('C\'est la distinction la plus importante du chapitre. Si seul le <b>prix du bien</b> change, on glisse <b>le long</b> de la courbe. Si <b>autre chose</b> change, c\'est <b>la courbe elle-même</b> qui se déplace.')
    c.p('Pour la demande, les « autres choses » sont le revenu des acheteurs et le prix des autres biens. Pour l\'offre, ce sont les coûts de production (matières premières, salaires).')
    c.tab(['', 'Courbe de demande', 'Courbe d\'offre'], [['Seul le prix du bien varie', 'Déplacement <b>le long</b> de la courbe', 'Déplacement <b>le long</b> de la courbe'], ['Une autre variable change', 'Déplacement <b>de</b> la courbe', 'Déplacement <b>de</b> la courbe']])
    c.pas('Exemple', ['Le prix du café baisse : les consommateurs en achètent plus → on glisse le long de la courbe de demande de café.', 'Les revenus augmentent : à chaque prix, on achète plus de café → toute la courbe de demande se déplace vers la droite.', 'Les salaires des producteurs augmentent : à chaque prix, ils offrent moins → la courbe d\'offre se déplace vers la gauche.'])
    c.df('Mécanisme de marché', 'Ajustement des prix jusqu\'à l\'équilibre : au-dessus de P*, excès d\'offre qui fait baisser le prix ; en dessous, excès de demande qui le fait monter.')
    c.df('Équilibre de marché', 'Prix P* et quantité Q* pour lesquels l\'offre est égale à la demande.')
    c.pourquoi('Pourquoi le prix finit-il par se fixer à P* ?', 'Si le prix est trop haut, les vendeurs ne trouvent pas preneur (excès d\'offre) : ils baissent leurs prix. S\'il est trop bas, des acheteurs repartent les mains vides (excès de demande) : les prix montent. Le seul prix stable est celui où offre et demande s\'égalisent.')
    c.retenir(['Demande décroissante, offre croissante ; équilibre là où elles se coupent.', 'Prix du bien → mouvement le long ; autre variable → déplacement de la courbe.', 'Excès d\'offre → prix ↓ ; excès de demande → prix ↑.'])
    c.sec('IV. Organisation du cours')
    c.ul(['CM de 27 h (9 séances de 3 h) et TD de 12 h (8 séances de 1 h 30).', 'Deux contrôles continus en amphi (CC1 vers mi-novembre, CC2 début janvier) et deux interrogations de 30 minutes en TD.', 'Moyenne = 0,5 × [0,5 × CC1 + 0,5 × TD] + 0,5 × CC2.', 'Manuels recommandés : Pindyck et Rubinfeld ; Picard ; Picard et Jullien (voir l\'onglet Auteurs & références).'])
    c.synthese(['Micro = décisions du consommateur et du producteur, à partir de la rationalité.', 'CPP : 5 hypothèses, chaque agent est preneur de prix.', 'Le prix d\'équilibre égalise offre et demande ; bien distinguer mouvement le long d\'une courbe et déplacement de la courbe.'])
    return c


def ch1():
    c = Cours()
    c.intro('De quoi parle ce chapitre ?',
            'Tu as un budget limité et deux biens à acheter. Combien de chacun ? C\'est toute la question de la théorie du consommateur. On va construire la réponse en trois étapes : <b>ce que tu peux acheter</b> (la contrainte budgétaire), <b>ce que tu préfères</b> (utilité et courbes d\'indifférence), puis <b>le meilleur choix</b> (l\'optimum). On verra enfin comment ce choix réagit quand les prix ou le revenu changent.',
            ['Quels paniers le budget permet-il ?', 'Comment représenter les goûts du consommateur ?', 'Comment trouver le panier optimal, graphiquement et par le calcul ?', 'Que se passe-t-il quand un prix ou le revenu change ?'])

    c.sec('Introduction : le consommateur et les paniers de biens')
    c.df('Consommateur', 'Agent économique (personne seule, foyer, ménage, communauté) qui acquiert et consomme des biens et services grâce à un revenu donné, pour en retirer une satisfaction.')
    c.df('Biens divisibles', 'Biens qui peuvent être achetés exactement dans la quantité souhaitée ; en microéconomie, on suppose les biens divisibles.')
    c.df('Panier de consommation', 'Combinaison de quantités de biens (x1 ; x2) ; il en existe une infinité.')
    c.p('Le consommateur sait <b>classer</b> tous les paniers : A ≻ B (A strictement préféré), A ≺ B, ou A ~ B (indifférent). On suppose aussi la <b>non-satiété</b> : il n\'est jamais rassasié.')

    c.sec('0. Ce que le consommateur peut acheter : la contrainte budgétaire')
    c.idee('Le consommateur ne peut pas dépenser plus que son revenu. Tous les paniers qu\'il peut s\'offrir forment un triangle ; ceux qui épuisent exactement son budget forment la <b>droite de budget</b>.')
    c.df('Contrainte budgétaire', 'Le consommateur ne peut pas dépenser plus que son revenu : D = p1x1 + p2x2 ≤ R.')
    c.df('Droite de budget', 'Ensemble des paniers pour lesquels la dépense égale exactement le revenu : R = p1x1 + p2x2.')
    c.f('x2 = R/p2 − (p1/p2) · x1 · coupe l\'axe x2 en R/p2 et l\'axe x1 en R/p1 · pente = −p1/p2')
    c.df('Prix relatif (pente en valeur absolue)', 'p1/p2 : valeur du bien 1 exprimée en unités de bien 2 du point de vue du marché ; pour 1 unité de plus de bien 1, il faut renoncer à p1/p2 unités de bien 2.')
    c.autrement('la pente dit « combien le marché me fait payer une unité de bien 1, en bien 2 ». Si p1 = 2 € et p2 = 5 €, une unité de bien 1 coûte 0,4 unité de bien 2.')
    c.pas('Exercice du cours pas à pas (R = 100, p1 = 2, p2 = 5)', [
        'Contrainte : 2x1 + 5x2 ≤ 100.', 'Droite : 5x2 = 100 − 2x1, donc x2 = 20 − 0,4x1.', 'Si x1 = 0 : x2 = 20 (tout le budget en bien 2). Si x2 = 0 : x1 = 50.',
        'P1 (10 ; 20) coûte 2 × 10 + 5 × 20 = 120 > 100 : inaccessible.', 'P2 (10 ; 5) coûte 45 < 100 : accessible. Avec x1 = 10, on pourrait aller jusqu\'à x2 = 16.', 'Pente 0,4 : une unité de bien 1 vaut 0,4 unité de bien 2 sur le marché.'])
    c.p('Comment la droite bouge : une hausse du <b>revenu</b> la déplace <b>parallèlement</b> vers l\'extérieur. Une hausse de <b>p1</b> la fait <b>pivoter</b> autour de R/p2 : on peut acheter moins de bien 1. Une hausse de <b>p2</b> la fait pivoter autour de R/p1.')
    c.retenir(['Droite de budget : x2 = R/p2 − (p1/p2)x1.', 'Pente = prix relatif p1/p2.', 'Revenu → déplacement parallèle ; prix → rotation.'])
    c.transition('On sait ce qu\'il <b>peut</b> acheter. Il faut maintenant savoir ce qu\'il <b>préfère</b> : c\'est la notion d\'utilité.')

    c.sec('1. Les notions d\'utilité')
    c.idee('L\'utilité mesure la <b>satisfaction</b>. Plus on consomme, plus on est satisfait, mais chaque unité supplémentaire apporte un peu moins de plaisir que la précédente.')
    c.df('Utilité', 'Satisfaction qu\'un agent retire de la consommation d\'un panier de biens.')
    c.df('Fonction d\'utilité', 'Relation U(x1 ; x2) qui associe un niveau d\'utilité à chaque panier ; pour chaque bien, elle est croissante à taux décroissant (dérivée première positive, dérivée seconde négative).')
    c.h3('A. Deux façons de voir l\'utilité')
    c.df('Utilité cardinale', 'Mesure quantitative de la satisfaction : si l\'utilité d\'un panier est le double de celle d\'un autre, il est préféré deux fois plus.')
    c.p('Exemple du cours (U = x1·√x2) : le panier (3 ; 9) donne U = 9 et le panier (9 ; 4) donne U = 18. On dirait alors que l\'agent préfère « deux fois plus » le second.')
    c.pourquoi('Pourquoi l\'approche cardinale est-elle critiquée ?', 'Parce que la satisfaction est subjective : personne ne peut dire qu\'il est « deux fois plus » content. Et surtout, on n\'en a pas besoin : pour choisir, il suffit de savoir quel panier on préfère, pas de combien.')
    c.df('Utilité ordinale', 'Indice relatif qui sert seulement à classer les paniers : U(A) > U(B) signifie seulement que A est préféré à B.')
    c.autrement('en ordinal, les chiffres ne servent qu\'à <b>ranger</b> les paniers, comme un classement : être premier ne veut pas dire être deux fois meilleur que le deuxième.')
    c.p('Conséquence : plusieurs fonctions donnent le même classement. Une fonction d\'utilité est définie <b>à une transformation monotone croissante près</b> : U = x1<sup>0,5</sup>x2<sup>0,5</sup> et V = 20 x1<sup>0,5</sup>x2<sup>0,5</sup> + 20 représentent les mêmes préférences.')
    c.h3('B. L\'utilité marginale')
    c.df('Utilité marginale', 'Satisfaction supplémentaire obtenue par la consommation d\'une unité supplémentaire d\'un bien, toutes choses égales par ailleurs : Um1 = ∂U/∂x1.')
    c.p('Elle est généralement <b>positive</b> (on est toujours un peu plus satisfait) et <b>décroissante</b> (de moins en moins).')
    c.autrement('le premier verre d\'eau quand on a soif apporte énormément ; le cinquième, beaucoup moins, mais toujours un peu.')
    c.retenir(['Utilité ordinale : on classe, on ne mesure pas.', 'Um = ∂U/∂x : positive et décroissante.'])
    c.transition('Pour représenter les préférences sur un graphique, on utilise les courbes d\'indifférence.')

    c.sec('2. Les préférences et les courbes d\'indifférence')
    c.h3('A. Quatre hypothèses sur les préférences')
    c.df('Complétude', 'Le consommateur est capable de comparer tous les paniers de biens : l\'ordre de préférence est complet.')
    c.df('Transitivité', 'Si A ≻ B et B ≻ C, alors A ≻ C (idem pour ~) : hypothèse de cohérence des préférences.')
    c.df('Monotonie', 'Non-satiété : plus l\'agent dispose de biens, plus sa satisfaction est élevée.')
    c.df('Convexité des préférences', 'Goût pour la diversité : l\'agent préfère les paniers diversifiés aux paniers « extrêmes ».')
    c.h3('B. Les courbes d\'indifférence')
    c.idee('Une courbe d\'indifférence relie tous les paniers qui rendent l\'agent <b>aussi heureux</b> les uns que les autres. Il lui est « indifférent » d\'avoir l\'un ou l\'autre.')
    c.df('Courbe d\'indifférence (CI)', 'Ensemble des paniers qui procurent au consommateur la même satisfaction (isoquant d\'utilité).')
    c.df('Carte d\'indifférence', 'Ensemble des courbes d\'indifférence d\'un consommateur ; plus une CI est éloignée de l\'origine, plus l\'utilité est élevée.')
    c.p('Chaque propriété des CI découle d\'une hypothèse :')
    c.tab(['Propriété des CI', 'Hypothèse', 'Pourquoi'], [['Plus loin de l\'origine = plus d\'utilité', 'Monotonie', 'Plus de biens = plus de satisfaction'], ['Pente négative', 'Monotonie', 'Si on a plus de bien 1, il faut moins de bien 2 pour rester aussi satisfait'],
                                                           ['Convexes (bombées vers l\'origine)', 'Convexité', 'On préfère les mélanges aux extrêmes'], ['Ne se croisent pas', 'Transitivité', 'Un croisement créerait une contradiction dans les préférences']])
    c.h3('C. Deux cas particuliers')
    c.df('Biens parfaitement substituables', 'Biens substituables à taux fixe : les CI sont des droites (TMS constant).')
    c.df('Biens parfaitement complémentaires', 'Biens consommés dans des proportions fixes : les CI sont coudées, en forme de L.')
    c.autrement('substituts parfaits : deux marques de sucre identiques, une vaut l\'autre. Compléments parfaits : chaussure gauche et chaussure droite, une seule ne sert à rien.')
    c.retenir(['CI = paniers de même satisfaction.', 'Décroissantes, convexes, ne se croisent pas, plus hautes = meilleures.'])
    c.transition('La forme de la CI dit combien l\'agent est prêt à échanger d\'un bien contre l\'autre : c\'est le TMS.')

    c.sec('3. Le taux marginal de substitution (TMS)')
    c.idee('Le TMS répond à la question : « <b>combien de bien 2 suis-je prêt à abandonner pour une unité de bien 1 de plus</b>, en restant aussi satisfait ? » C\'est le prix que le consommateur, lui, accorde au bien 1.')
    c.df('Taux marginal de substitution (TMS)', 'Quantité de bien 2 à laquelle le consommateur est prêt à renoncer pour obtenir une unité supplémentaire de bien 1 en gardant sa satisfaction constante ; c\'est la valeur du bien 1 exprimée en bien 2.')
    c.f('Définition 1 : TMS = −Δx2/Δx1 = pente de la CI en valeur absolue<br>Définition 2 : TMS = Um1 / Um2')
    c.pourquoi('Pourquoi TMS = Um1/Um2 ?', 'Le long d\'une CI, l\'utilité ne change pas : dU = Um1·dx1 + Um2·dx2 = 0. Donc −dx2/dx1 = Um1/Um2. Autrement dit, ce que je gagne avec le bien 1 (Um1) doit compenser exactement ce que je perds avec le bien 2 (Um2).')
    c.ul(['Si pour 1 unité de bien 1 il faut renoncer à 0,5 unité de bien 2 : TMS = −(−0,5/1) = 0,5.', 'Lecture inverse : TMS = 0,6 veut aussi dire que l\'agent veut récupérer 0,6 unité de bien 2 s\'il cède 1 unité de bien 1.', 'Le TMS <b>diminue</b> le long d\'une CI : plus on a de bien 1, moins on est prêt à sacrifier de bien 2 pour en avoir encore. C\'est ce qui rend la CI convexe.'])
    c.pas('Exemple du cours pas à pas : U = x1^0,5 x2^0,5', ['Um1 = 0,5 x1<sup>−0,5</sup>x2<sup>0,5</sup> et Um2 = 0,5 x1<sup>0,5</sup>x2<sup>−0,5</sup>.', 'TMS = Um1/Um2 = x2/x1.', 'Panier A (4 ; 9) : U = 6 et TMS = 9/4 = 2,25. L\'agent a peu de bien 1, il est prêt à céder beaucoup de bien 2.', 'Panier B (36 ; 1) : U = 6 et TMS = 1/36 ≈ 0,028. Il a beaucoup de bien 1, il ne céderait presque rien.'],
          'Avec U = 20 x1<sup>0,5</sup>x2<sup>0,5</sup> + 20, le TMS est le même : on retrouve que deux fonctions d\'utilité peuvent décrire les mêmes préférences.')
    c.retenir(['TMS = −Δx2/Δx1 = Um1/Um2.', 'Décroissant le long d\'une CI.', 'C\'est le « prix subjectif » du bien 1.'])
    c.transition('On a maintenant deux « prix » du bien 1 : celui du consommateur (TMS) et celui du marché (p1/p2). L\'optimum est là où ils coïncident.')

    c.sec('4. L\'optimum du consommateur')
    c.idee('Le meilleur panier est celui qui se trouve <b>sur la droite de budget</b> (on dépense tout) et sur la <b>courbe d\'indifférence la plus haute possible</b>. Graphiquement, c\'est le point où la droite <b>touche</b> une CI sans la couper.')
    c.h3('A. Approche graphique')
    c.df('Optimum du consommateur', 'Panier situé au point de tangence entre la droite de budget et la courbe d\'indifférence la plus haute possible : TMS = p1/p2.')
    c.f('À l\'optimum : TMS = p1/p2')
    c.pourquoi('Pourquoi un panier où TMS ≠ p1/p2 n\'est-il pas optimal ?', 'Prenons TMS = 0,7 et p1/p2 = 0,5. L\'agent serait prêt à céder 0,7 unité de bien 2 pour une unité de bien 1, mais le marché ne lui en demande que 0,5 : il gagne à l\'échange et achète plus de bien 1. Il continue tant que TMS > p1/p2. Si au contraire TMS = 0,3 < 0,5, il fait l\'inverse : il cède du bien 1, car le marché lui rend 0,5 unité de bien 2 alors que 0,3 lui suffirait. Il ne s\'arrête que quand TMS = p1/p2.')
    c.h3('B. Approche mathématique')
    c.f('Programme : Max U(x1 ; x2) sous contrainte R = p1x1 + p2x2')
    c.df('Lagrangien', 'Fonction à trois variables L(x1 ; x2 ; λ) = U(x1 ; x2) + λ(R − p1x1 − p2x2) dont on annule les dérivées partielles pour trouver l\'optimum sous contrainte.')
    c.f('∂L/∂x1 = Um1 − λp1 = 0 · ∂L/∂x2 = Um2 − λp2 = 0 · ∂L/∂λ = R − p1x1 − p2x2 = 0 ⇒ Um1/p1 = Um2/p2 ⇔ Um1/Um2 = p1/p2')
    c.autrement('à l\'optimum, le dernier euro dépensé rapporte la même satisfaction, qu\'il serve à acheter du bien 1 ou du bien 2 (Um1/p1 = Um2/p2). Sinon, il vaudrait mieux déplacer cet euro vers le bien qui rapporte le plus.')
    c.p('Les conditions du second ordre sont supposées vérifiées : les CPO suffisent quand les CI sont convexes. <b>Méthode rapide</b> : résoudre directement { TMS = p1/p2 ; R = p1x1 + p2x2 }.')
    c.pas('Exemple 1 du cours : U = x1^0,5 x2^0,5, R = 100, p1 = 2, p2 = 5', ['TMS = x2/x1 ; p1/p2 = 0,4.', 'Condition d\'optimum : x2/x1 = 0,4, donc x2 = 0,4 x1.', 'On remplace dans le budget : 100 = 2x1 + 5 × 0,4x1 = 4x1.', 'x1 = 25, puis x2 = 0,4 × 25 = 10.'], 'Optimum (25 ; 10). Vérification : 2 × 25 + 5 × 10 = 100.')
    c.pas('Exemple 2 du cours : U = x1^0,25 x2^0,75, R = 400, p1 = 10, p2 = 20', ['TMS = (0,25/0,75) · x2/x1 = x2/(3x1).', 'x2/(3x1) = 10/20 ⇒ x2 = 1,5 x1.', '400 = 10x1 + 20 × 1,5x1 = 40x1 ⇒ x1 = 10.', 'x2 = 15.'])
    c.note('Astuce de vérification : avec U = x1<sup>a</sup>x2<sup>b</sup>, l\'agent dépense la part a/(a+b) de son revenu en bien 1. Pour l\'exemple 2 : 25 % de 400 = 100 €, soit 10 unités à 10 €.')
    c.h3('C. Cas particuliers')
    c.df('Solution en coin', 'Optimum où l\'agent ne consomme qu\'un seul des deux biens : TMS ≠ p1/p2 à l\'extrémité de la droite de budget.')
    c.ul(['Substituts parfaits (CI droites) : si p1/p2 = TMS, tous les paniers de la droite sont optimaux ; si p1/p2 < TMS, l\'agent ne prend que du bien 1 ; si p1/p2 > TMS, que du bien 2.', 'Compléments parfaits (CI en L) : l\'optimum est au coin, dans la proportion fixe.'])
    c.retenir(['Optimum : sur la droite de budget et TMS = p1/p2.', 'Méthode : TMS = p1/p2, puis on remplace dans le budget.', 'Lagrangien : Um1/p1 = Um2/p2.'])
    c.transition('L\'optimum dépend des prix et du revenu. Que se passe-t-il quand ils changent ? C\'est ce qui donne la <b>fonction de demande</b>.')

    c.sec('5. Fonction de demande, variations de prix et de revenu')
    c.h3('A. La fonction de demande')
    c.idee('Au lieu de résoudre l\'optimum pour des chiffres précis, on le résout avec des lettres (p1, p2, R). On obtient une formule qui donne la quantité demandée <b>pour n\'importe quels prix et revenu</b> : c\'est la fonction de demande.')
    c.df('Fonction de demande', 'Expression des quantités optimales en fonction des prix et du revenu : elle donne tous les paniers optimaux ; en tout point de la courbe de demande, l\'agent maximise son utilité.')
    c.pas('Exemple du cours : TMS = x2/(2x1)', ['À l\'optimum : x2/(2x1) = p1/p2, donc p2x2 = 2p1x1.', 'Budget : R = p1x1 + 2p1x1 = 3p1x1.', 'Donc x1 = R/(3p1) et x2 = 2R/(3p2).', 'Avec R = 120 : x1 = 40/p1 et x2 = 80/p2 ; pour p1 = 5 et p2 = 8, le panier optimal est (8 ; 10).'])
    c.h3('Rappel : les élasticités')
    c.idee('Une élasticité mesure la <b>sensibilité</b> : de combien de % varie une quantité quand une autre variable augmente de 1 %.')
    c.df('Élasticité', 'Pourcentage de variation d\'une variable suite à une variation de 1 % d\'une autre variable.')
    c.f('E(y/x) = Δy% / Δx% = (Δy/Δx)·(x/y) → (∂y/∂x)·(x/y)')
    c.pas('Deux exemples du cours', ['x passe de 2 à 4 (+100 %) et y de 10 à 14 (+40 %) : E = 40/100 = 0,4. Si x augmente de 1 %, y augmente de 0,4 %.', 'y = −5x + 20 en x = 2 (y = 10) : ∂y/∂x = −5, donc E = −5 × 2/10 = −1. Si x augmente de 1 %, y baisse de 1 %.'])
    c.df('Élasticité-prix directe', 'Variation en % de la quantité demandée d\'un bien suite à une hausse de 1 % de son propre prix ; en général négative.')
    c.p('Exemple : x = −20p + 1000 en p = 25 (x = 500) : E = −20 × 25/500 = −1. Entre −1 et 1, la demande est <b>inélastique</b> (courbe très verticale, on achète presque autant malgré la hausse) ; au-delà, elle est <b>élastique</b> (courbe aplatie).')
    c.tab(['Élasticité-prix', 'Type de bien'], [['E < 0', 'Bien ordinaire'], ['E > 0', 'Bien de Giffen, effet Veblen']])
    c.df('Bien de Giffen', 'Bien inférieur dont la demande augmente quand son prix augmente, parce que l\'effet revenu l\'emporte sur l\'effet de substitution.')
    c.df('Effet Veblen', 'Hausse de la demande d\'un bien quand son prix augmente, parce que le prix élevé signale un statut (consommation ostentatoire).')
    c.df('Élasticité-revenu', 'Variation en % de la quantité demandée suite à une hausse de 1 % du revenu : E = (∂x/∂R) · (R/x).')
    c.tab(['Élasticité-revenu', 'Type de bien', 'Exemple du cours'], [['E < 0', 'Bien inférieur', ''], ['0 < E < 1', 'Bien normal de première nécessité', 'Alimentation : de 15 à 30 quand le revenu passe de 20 à 60'], ['E > 1', 'Bien normal de luxe (supérieur)', 'Cinéma : de 5 à 30 pour la même hausse de revenu']])
    c.df('Élasticité-prix croisée', 'Variation en % de la quantité demandée d\'un bien suite à une hausse de 1 % du prix d\'un autre bien : positive pour des substituts, négative pour des compléments.')
    c.p('Exemple : p<sub>y</sub> passe de 5 à 8 (+60 %) et x de 5 à 6 (+20 %) : E = 0,33 > 0, les biens sont substituables.')
    c.tab(['', 'La demande augmente', 'La demande diminue'], [['Le prix du bien augmente', 'Giffen, Veblen', 'Biens ordinaires'], ['Le revenu augmente', 'Biens normaux (nécessité, luxe)', 'Biens inférieurs'], ['Le prix d\'un autre bien augmente', 'Substituables', 'Complémentaires']])
    c.h3('B. Quand le prix ou le revenu varie')
    c.df('Courbe de consommation-prix', 'Lieu des paniers optimaux quand le prix d\'un bien varie (revenu et autre prix constants) ; elle permet de déduire la courbe de demande.')
    c.p('Exemple du cours : R = 20, p2 = 2 et p1 = 2, puis 1, puis 0,5. La droite de budget pivote, les optimums A, B, C forment la courbe de consommation-prix. En reportant chaque (x1 ; p1), on trace la courbe de demande du bien 1. Le long de cette courbe, l\'agent maximise toujours (TMS = p1/p2), mais son niveau d\'utilité change.')
    c.df('Courbe de consommation-revenu', 'Lieu des paniers optimaux quand le revenu varie (prix constants) ; chaque hausse de revenu déplace la courbe de demande.')
    c.df('Courbe d\'Engel', 'Courbe qui relie la quantité consommée d\'un bien au revenu de l\'agent (une courbe par bien) ; croissante pour un bien normal, décroissante pour un bien inférieur.')
    c.h3('C. Effet de substitution et effet de revenu')
    c.idee('Quand le prix du bien 1 baisse, deux choses se passent en même temps : le bien 1 devient <b>relativement moins cher</b> que le bien 2 (on en achète plus à sa place) et on devient <b>plus riche</b> en pouvoir d\'achat (on peut acheter plus de tout). Hicks sépare ces deux effets.')
    c.df('Effet-prix (effet total)', 'Variation de la quantité demandée d\'un bien suite à la variation de son prix ; il se décompose en effet de substitution et effet de revenu (décomposition de Hicks).')
    c.df('Effet de substitution (ES)', 'Variation de la demande liée à la seule variation des prix relatifs, à utilité constante : le bien devenu relativement moins cher est davantage consommé.')
    c.df('Effet de revenu (ER)', 'Variation de la demande liée à la variation du pouvoir d\'achat provoquée par la variation de prix (le revenu nominal est inchangé).')
    c.p('Exemple du cours : avec 100 € et un bien à 10 €, on peut en acheter 10. Si le prix passe à 5 €, on peut en acheter 20 : le revenu n\'a pas bougé, mais le pouvoir d\'achat a doublé.')
    c.df('Méthode de Hicks', 'Décomposition en trois paniers : initial (prix et revenu initiaux), intermédiaire (nouveaux prix, utilité initiale, revenu « compensé » R\'), final (nouveaux prix, revenu initial). ES = initial → intermédiaire ; ER = intermédiaire → final.')
    c.autrement('le panier intermédiaire répond à la question « qu\'achèterait l\'agent avec les nouveaux prix s\'il n\'était ni plus riche ni plus pauvre ? ». Le passage de l\'initial à l\'intermédiaire, c\'est la pure substitution ; le reste, c\'est l\'enrichissement.')
    c.tab(['Si p1 diminue', 'Effet sur x1', 'Effet sur x2'], [['ES', 'Hausse', 'Baisse'], ['ER (biens normaux)', 'Hausse', 'Hausse'], ['ET', 'Hausse : bien ordinaire', 'Hausse si ER > ES, baisse si ER < ES']])
    c.p('<b>Bien inférieur</b> : l\'ER joue à l\'envers (plus riche, on en achète moins). Si cet ER négatif l\'emporte sur l\'ES, la baisse de prix fait <b>baisser</b> la demande : c\'est un <b>bien de Giffen</b>.')
    c.pas('Exemple chiffré du cours : U = x1^0,25 x2^0,75, R = 1 000, p2 = 2, p1 passe de 10 à 5', ['Panier initial : x1 = 0,25 × 1 000/10 = 25 ; x2 = 0,75 × 1 000/2 = 375.', 'Panier final (p1 = 5, même revenu) : x1 = 50 ; x2 = 375.', 'Panier intermédiaire (p1 = 5, même utilité qu\'au départ) : x1 ≈ 42 ; x2 ≈ 315.', 'ES : x1 +17, x2 −60. ER : x1 +8, x2 +60. ET : x1 +25, x2 0.'],
          'ER > 0 : biens normaux ; le bien 1 est ordinaire ; pour x2, les deux effets se compensent (biens indépendants).')
    c.retenir(['Fonction de demande = optimum exprimé en fonction de p1, p2, R.', 'Élasticités : prix (< 0 en général), revenu (< 0 inférieur, 0-1 nécessité, > 1 luxe), croisée (> 0 substituts, < 0 compléments).', 'ET = ES + ER (Hicks) ; Giffen si l\'ER négatif l\'emporte.'])
    c.synthese(['Le consommateur maximise son utilité sous sa contrainte budgétaire.', 'Outils : droite de budget (pente p1/p2), courbes d\'indifférence, TMS = Um1/Um2.', 'Optimum : TMS = p1/p2 et budget saturé (Lagrangien ou méthode rapide).', 'Quand les prix ou le revenu changent : fonction de demande, élasticités, courbes de consommation-prix, consommation-revenu, d\'Engel, et décomposition ES + ER.'])
    return c


def ch2():
    c = Cours()
    c.intro('De quoi parle ce chapitre ?',
            'Le producteur fait face à un problème qui ressemble beaucoup à celui du consommateur. Pour produire une quantité donnée, il peut combiner plus de machines et moins de travailleurs, ou l\'inverse. <b>Quelle combinaison coûte le moins cher ?</b> Une fois cette question réglée, on peut en déduire ses coûts pour chaque niveau de production.',
            ['Comment mesurer l\'efficacité des facteurs (productivités) ?', 'Que se passe-t-il quand on augmente tous les facteurs (rendements d\'échelle) ?', 'Comment trouver la combinaison de facteurs la moins chère ?', 'Comment se comportent les coûts à court et à long terme ?'])

    c.sec('Introduction : le producteur')
    c.df('Production', 'Opération qui transforme certains biens et services existants (inputs) en d\'autres biens et services (output).')
    c.df('Entreprise', 'Agent qui organise l\'activité de production et en tire un profit ; contrairement au consommateur, elle fabrique avant de vendre.')
    c.df('Technologie de production', 'Façon dont les inputs (intrants, facteurs de production) sont transformés en output (extrant) ; les inputs génèrent des coûts.')
    c.p('Le producteur est contraint par sa technologie et par les prix (des facteurs et du bien). Son objectif : trouver la combinaison de facteurs qui <b>minimise le coût</b>, puis la quantité qui <b>maximise le profit</b>.')

    c.sec('1. Facteurs, fonction de production et productivités')
    c.idee('La fonction de production est une « recette » : pour telle quantité de capital et de travail, voilà combien on peut produire au maximum.')
    c.p('Trois types d\'inputs : le <b>travail</b>, les <b>matières premières</b> et le <b>capital</b>.')
    c.df('Facteur fixe', 'Facteur dont la quantité ne varie pas (à court terme).')
    c.df('Facteur variable', 'Facteur dont la quantité varie avec le niveau de production ; à long terme, tous les facteurs sont variables.')
    c.autrement('à court terme, on ne peut pas construire une usine en une semaine : le capital est fixe, on ne joue que sur le travail. À long terme, on peut tout changer.')
    c.df('Facteurs substituables', 'Facteurs qui peuvent se remplacer l\'un l\'autre en maintenant la production.')
    c.df('Facteurs complémentaires', 'Facteurs combinés dans des proportions fixes.')
    c.df('Fonction de production', 'Relation technique y = f(K, L) qui donne, pour chaque combinaison d\'inputs, le niveau maximal d\'output.')
    c.h3('Productivités moyenne et marginale')
    c.df('Productivité moyenne (PM)', 'Quantité produite par unité d\'input : PML = f(K, L)/L ; PMK = f(K, L)/K.')
    c.df('Productivité marginale (Pm)', 'Accroissement de la production dû à l\'utilisation d\'une unité supplémentaire d\'un facteur, toutes choses égales par ailleurs : PmL = Δf/ΔL → ∂f/∂L.')
    c.warn('Notation du cours : <b>PML</b> = productivité <b>moyenne</b>, <b>PmL</b> = productivité <b>marginale</b>. Le « m » minuscule veut dire marginal.')
    c.autrement('la moyenne, c\'est « combien produit un travailleur en moyenne » ; la marginale, c\'est « combien ajoute le <b>dernier</b> travailleur embauché ».')
    c.tab(['L', 'K', 'y', 'PML (moyenne) = y/L', 'PmL (marginale) = Δy'], [[0, 10, 0, '—', '—'], [1, 10, 10, 10, 10], [2, 10, 30, 15, 20], [3, 10, 60, 20, 30], [4, 10, 80, 20, 20], [5, 10, 94, '18,80', 14], [6, 10, 103, '17,17', 9], [7, 10, 107, '15,29', 4], [8, 10, 107, '13,38', 0], [9, 10, 104, '11,56', -3]], num_cols=(0, 1, 2, 3, 4))
    c.p('Lecture du tableau : les premiers travailleurs sont de plus en plus efficaces (la PmL monte jusqu\'à 30), puis chaque nouveau travailleur apporte de moins en moins. Le 9ᵉ fait même baisser la production : il gêne les autres, avec seulement 10 machines.')
    c.df('Loi des rendements marginaux décroissants', 'Au-delà d\'un certain seuil, chaque unité supplémentaire d\'un facteur variable (l\'autre étant fixe) accroît de moins en moins la production.')
    c.pourquoi('Pourquoi la PmL coupe-t-elle la PML en son maximum ?', 'C\'est comme une moyenne de notes. Si ta dernière note (la marginale) est au-dessus de ta moyenne, ta moyenne monte ; si elle est en dessous, ta moyenne baisse. La moyenne est donc au plus haut exactement quand la dernière note lui est égale.')
    c.h3('Les rendements d\'échelle')
    c.df('Rendements d\'échelle', 'Taux auquel la production augmente quand toutes les quantités de facteurs augmentent dans la même proportion (analyse de long terme).')
    c.f('Pour λ > 1 : f(λz) > λf(z) → croissants · f(λz) = λf(z) → constants · f(λz) < λf(z) → décroissants')
    c.autrement('si on double tout (usines et salariés) : la production fait plus que doubler (croissants), double (constants) ou moins que doubler (décroissants).')
    c.note('Pour y = K<sup>α</sup>L<sup>β</sup> : f(λK, λL) = λ<sup>α+β</sup>y. Rendements croissants si α + β > 1, constants si = 1, décroissants si < 1.')
    c.retenir(['PML = y/L (moyenne) ; PmL = Δy/ΔL (marginale).', 'Rendements marginaux décroissants : un facteur fixe, l\'autre augmente.', 'Rendements d\'échelle : tous les facteurs augmentent dans la même proportion (long terme).'])
    c.transition('Plusieurs combinaisons de K et L permettent la même production. Les isoquantes les représentent.')

    c.sec('2. Isoquantes et TMST')
    c.idee('Une isoquante est l\'équivalent, pour le producteur, de la courbe d\'indifférence : elle relie toutes les combinaisons de facteurs qui donnent la <b>même production</b>.')
    c.df('Isoquante', 'Courbe qui relie toutes les combinaisons de facteurs permettant d\'obtenir le même niveau de production ; un ensemble d\'isoquantes forme une carte d\'isoquantes.')
    c.p('Exemple du cours : (L ; K) = (1 ; 5), (2 ; 3), (3 ; 2), (5 ; 1) produisent tous 100 unités. Les isoquantes sont <b>décroissantes</b> et <b>convexes</b> ; la production augmente en s\'éloignant de l\'origine.')
    c.df('Taux marginal de substitution technique (TMST)', 'Réduction de la quantité de capital qui permet de maintenir la production constante quand on utilise une unité de travail en plus.')
    c.f('Définition 1 : TMST = −ΔK/ΔL = pente de l\'isoquante en valeur absolue · Définition 2 : TMST = PmL / PmK')
    c.pourquoi('Pourquoi TMST = PmL/PmK ?', 'Le long d\'une isoquante, la production ne change pas : dy = PmK·dK + PmL·dL = 0, donc −dK/dL = PmL/PmK. Si un travailleur de plus produit autant que deux machines, on peut retirer deux machines pour chaque travailleur ajouté.')
    c.p('Le TMST est décroissant : plus on a déjà de travail, moins une unité de travail supplémentaire permet d\'économiser de capital. Cas particuliers : facteurs parfaitement substituables (isoquantes droites) et proportions fixes (isoquantes en L).')
    c.retenir(['Isoquante = même production.', 'TMST = −ΔK/ΔL = PmL/PmK, décroissant.'])
    c.transition('Parmi toutes les combinaisons d\'une isoquante, laquelle coûte le moins cher ? Il faut faire entrer les prix des facteurs.')

    c.sec('3. Minimiser le coût de production')
    c.idee('C\'est le miroir du consommateur. Lui maximisait sa satisfaction avec un budget donné ; le producteur <b>minimise son coût</b> pour une production donnée.')
    c.df('Droite d\'isocoût', 'Ensemble des combinaisons de capital et de travail qui coûtent le même montant : C = pK·K + pL·L ; équivalent de la droite de budget.')
    c.f('K = C/pK − (pL/pK)·L · pente = −pL/pK')
    c.p('La pente pL/pK est la valeur du travail en capital sur le marché (si elle vaut 2, un travailleur coûte autant que 2 unités de capital).')
    c.pas('Illustration du cours : produire y = 10 avec y = K^0,5 L^0,5, pK = 1 €, pL = 2 €', ['K = 1, L = 100 : coût 1 + 200 = 201 €.', 'K = 2, L = 50 : coût 2 + 100 = 102 €.', 'K = 10, L = 10 : coût 10 + 20 = 30 €.', 'Toutes ces combinaisons produisent 10, mais leurs coûts sont très différents : il faut trouver la moins chère.'])
    c.df('Combinaison optimale de facteurs', 'Point de tangence entre l\'isoquante du niveau de production voulu et la droite d\'isocoût la plus proche de l\'origine : TMST = pL/pK.')
    c.f('Min C = pK·K + pL·L sous y = f(K, L) · L(K, L, λ) = pK·K + pL·L + λ(ȳ − f(K, L)) · CPO ⇒ PmL/PmK = pL/pK')
    c.autrement('à l\'optimum, le dernier euro dépensé en travail rapporte autant de production que le dernier euro dépensé en capital (PmL/pL = PmK/pK).')
    c.pas('Exemple du cours pas à pas : y = K^0,5 L^0,5, ȳ = 10, pK = 1, pL = 2', ['TMST = PmL/PmK = K/L.', 'Condition : K/L = pL/pK = 2, donc K = 2L.', 'Contrainte : 10 = (2L)<sup>0,5</sup>L<sup>0,5</sup> = √2 · L, donc L = 10/√2 ≈ 7,07.', 'K = 2L ≈ 14,14.', 'Coût minimal : 14,14 + 2 × 7,07 ≈ 28,28 €. C\'est moins que les 30 € de (10 ; 10).'])
    c.retenir(['Isocoût : C = pK·K + pL·L, pente pL/pK.', 'Optimum : TMST = pL/pK, puis la contrainte de production.'])
    c.transition('En refaisant ce calcul pour toutes les quantités, on obtient le chemin que suit l\'entreprise quand elle grandit.')

    c.sec('4. Sentier d\'expansion et demande de facteurs')
    c.df('Sentier (chemin) d\'expansion', 'Courbe qui relie les combinaisons de facteurs qui minimisent le coût pour chaque niveau d\'output ; son équation K = f(L) découle de TMST = pL/pK.')
    c.p('Exemple : y = K<sup>0,5</sup>L<sup>0,5</sup>, pK = 1, pL = 2 ⇒ K/L = 2 ⇒ sentier <b>K = 2L</b>. Quelle que soit la production, l\'entreprise garde deux fois plus de capital que de travail.')
    c.df('Fonction de demande de facteurs', 'Quantité de chaque facteur qui minimise le coût en fonction des prix des facteurs et de la quantité produite (une fonction par facteur).')
    c.p('Même exemple : K = 2y/√2 = √2·y et L = y/√2. Ce sont les « fonctions de demande » de capital et de travail.')

    c.sec('5. Les coûts')
    c.h3('A. Les coûts de court terme')
    c.idee('À court terme, une partie des coûts ne dépend pas de la quantité produite (loyer, machines) : ce sont les coûts <b>fixes</b>. Les autres suivent la production : ce sont les coûts <b>variables</b>.')
    c.df('Coût fixe (CF)', 'Coût qui ne varie pas avec le niveau de production et ne peut être éliminé qu\'en cessant l\'activité.')
    c.df('Coût variable (CV)', 'Coût qui varie avec le niveau de production.')
    c.df('Coût moyen (CM)', 'Coût total par unité produite : CM = C/y = CVM + CFM.')
    c.df('Coût marginal (Cm)', 'Coût de production d\'une unité supplémentaire : Cm = ΔC/Δy = ΔCV/Δy → ∂C/∂y.')
    c.f('C = CV + CF · CM = C/y = CVM + CFM · CVM = pL/PML · Cm = pL/PmL')
    c.pourquoi('Pourquoi Cm = pL/PmL ?', 'Produire une unité de plus demande 1/PmL travailleur en plus, qui coûte chacun pL. Donc quand la productivité marginale baisse (rendements décroissants), le coût marginal monte : c\'est la même réalité vue sous deux angles.')
    c.tab(['y', 'CF', 'CV', 'CT', 'CM', 'CFM', 'CVM', 'Cm'], [[1, 50, 50, 100, 100, 50, 50, 50], [2, 50, 78, 128, 64, 25, 39, 28], [3, 50, 98, 148, '49,3', '16,7', '32,7', 20], [4, 50, 112, 162, '40,5', '12,5', 28, 14], [5, 50, 130, 180, 36, 10, 26, 18], [6, 50, 150, 200, '33,3', '8,3', 25, 20], [7, 50, 175, 225, '32,1', '7,1', 25, 25], [8, 50, 204, 254, '31,8', '6,3', '25,5', 29], [9, 50, 242, 292, '32,4', '5,6', '26,9', 38], [10, 50, 300, 350, 35, 5, 30, 58], [11, 50, 385, 435, '39,5', '4,5', 35, 85]], num_cols=tuple(range(8)))
    c.p('Lecture : le CFM baisse toujours (les 50 € fixes sont répartis sur plus d\'unités). Le Cm baisse jusqu\'à y = 4, puis monte. Le Cm coupe le CVM puis le CM <b>en leur minimum</b>, pour la même raison que la marginale et la moyenne en productivité.')
    c.h3('B. Les coûts de long terme')
    c.df('Courbe de coût minimal (coût total de long terme)', 'Courbe qui relie, pour chaque niveau d\'output, le coût minimum de production ; elle contient la même information que le chemin d\'expansion.')
    c.p('Exemple : C = pK·K + pL·L = 1 × √2·y + 2 × y/√2 = <b>2√2·y</b>. Le coût est proportionnel à la production : rendements d\'échelle constants (0,5 + 0,5 = 1).')
    c.tab(['Rendements d\'échelle', 'Coût total de long terme'], [['Croissants', 'Augmente moins vite que la production (courbe concave)'], ['Constants', 'Augmente comme la production (droite)'], ['Décroissants', 'Augmente plus vite que la production (courbe convexe)']])
    c.p('À long terme, tous les facteurs sont variables : <b>C<sub>LT</sub> ≤ C<sub>CT</sub></b>. À court terme, le capital est bloqué : on ne peut pas toujours se placer sur le sentier d\'expansion, donc on paie au moins autant.')
    c.df('Profit', 'Différence entre les recettes et les coûts de l\'entreprise : π = RT − C = p·y − C.')
    c.synthese(['Productivités : moyenne (y/L) et marginale (Δy/ΔL) ; rendements marginaux décroissants à court terme.', 'Rendements d\'échelle : comparer f(λK, λL) et λf(K, L) ; pour une Cobb-Douglas, comparer α + β à 1.', 'Coût minimal : TMST = PmL/PmK = pL/pK, puis sentier d\'expansion et demandes de facteurs.', 'Coûts : CT = CF + CV ; Cm coupe CM et CVM en leur minimum ; C<sub>LT</sub> ≤ C<sub>CT</sub>.'])
    return c
